CREATE TABLE product_categories (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, CONSTRAINT product_categories_org_name_key UNIQUE(organization_id,name));
CREATE TABLE products (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, category_id UUID REFERENCES product_categories(id) ON DELETE SET NULL, name VARCHAR(180) NOT NULL, sku VARCHAR(80), barcode VARCHAR(120), tax_rate_bps INTEGER NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, is_combo BOOLEAN NOT NULL DEFAULT false, combo_items JSONB NOT NULL DEFAULT '[]', modifier_config JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), CONSTRAINT products_org_sku_key UNIQUE(organization_id,sku), CONSTRAINT products_org_barcode_key UNIQUE(organization_id,barcode));
CREATE TABLE product_variants (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, price_minor INTEGER NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, CONSTRAINT product_variants_product_name_key UNIQUE(product_id,name));
CREATE TABLE product_prices (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, branch_id UUID NOT NULL, product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, price_minor INTEGER NOT NULL, CONSTRAINT product_prices_branch_product_key UNIQUE(branch_id,product_id), CONSTRAINT product_prices_branch_org_fk FOREIGN KEY(branch_id,organization_id) REFERENCES branches(id,organization_id) ON DELETE CASCADE);
CREATE TABLE register_sessions (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, branch_id UUID NOT NULL, opened_by_id UUID NOT NULL, opening_float_minor INTEGER NOT NULL, opened_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), closed_at TIMESTAMPTZ(3), CONSTRAINT register_sessions_branch_org_fk FOREIGN KEY(branch_id,organization_id) REFERENCES branches(id,organization_id) ON DELETE RESTRICT);
CREATE TABLE pos_orders (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, branch_id UUID NOT NULL, register_id UUID REFERENCES register_sessions(id) ON DELETE SET NULL, created_by_id UUID NOT NULL, order_number INTEGER NOT NULL, order_type VARCHAR(30) NOT NULL DEFAULT 'TAKEAWAY', status VARCHAR(30) NOT NULL DEFAULT 'PAID', subtotal_minor INTEGER NOT NULL, tax_minor INTEGER NOT NULL, total_minor INTEGER NOT NULL, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), CONSTRAINT pos_orders_org_number_key UNIQUE(organization_id,order_number), CONSTRAINT pos_orders_branch_org_fk FOREIGN KEY(branch_id,organization_id) REFERENCES branches(id,organization_id) ON DELETE RESTRICT);
CREATE TABLE pos_order_items (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, order_id UUID NOT NULL REFERENCES pos_orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT, variant_id UUID REFERENCES product_variants(id) ON DELETE SET NULL, name_snapshot VARCHAR(180) NOT NULL, quantity INTEGER NOT NULL, unit_price_minor INTEGER NOT NULL, tax_minor INTEGER NOT NULL, line_total_minor INTEGER NOT NULL, modifiers JSONB NOT NULL DEFAULT '[]');
CREATE TABLE pos_order_payments (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, order_id UUID NOT NULL REFERENCES pos_orders(id) ON DELETE CASCADE, method VARCHAR(40) NOT NULL, amount_minor INTEGER NOT NULL, reference VARCHAR(160), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE pos_receipts (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, order_id UUID NOT NULL UNIQUE REFERENCES pos_orders(id) ON DELETE RESTRICT, receipt_number VARCHAR(50) NOT NULL, issued_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), CONSTRAINT pos_receipts_org_number_key UNIQUE(organization_id,receipt_number));
CREATE INDEX products_org_active_idx ON products(organization_id,is_active); CREATE INDEX pos_orders_org_branch_created_idx ON pos_orders(organization_id,branch_id,created_at); CREATE INDEX register_sessions_org_branch_closed_idx ON register_sessions(organization_id,branch_id,closed_at);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['product_categories','products','product_variants','product_prices','register_sessions','pos_orders','pos_order_items','pos_order_payments','pos_receipts'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (organization_id = NULLIF(current_setting(''app.organization_id'',true),'''')::uuid OR current_user = ''cafe_pos_platform'')',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO cafe_pos_runtime',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO cafe_pos_platform',t); END LOOP; END $$;
